    /** Все слова банка — допустимые попытки; статьи добавляют слова сверх банка, если такие появятся. */
    private val knownWords = ALL_WORDS + articles.map { it.word }

    fun isValid(word: String): Boolean = word.uppercase() in knownWords

    fun articleOf(word: String): Article? = articles.firstOrNull { it.word == word.uppercase() }

    /** Deterministic pick, changes once per day. No java.time — minSdk 24 without desugaring. */
    fun wordOfTheDay(nowMillis: Long = System.currentTimeMillis()): String {
        val day = nowMillis / 86_400_000L
        val idx = ((day % articles.size) + articles.size).toInt() % articles.size
        return articles[idx].word
    }

    /**
     * Случайное слово для партии: всегда из статей — подсказка (Пример 4) и
     * статья «Словаря» (Примеры 5–6) обязаны работать на любом слове.
     * [exclude] — не возвращать его: реролл рестарта не должен повторить
     * только что сыгранное слово. Сценарии записи (демо-панель) проходят
     * мимо — через wordOverride в DemoConfig.
     */
    fun randomWord(exclude: String? = null): String =
        articles.map { it.word }.filter { it != exclude }.random()
}
